const ART=parent.REVIEW_ART, FULL_ART=parent.REVIEW_FULL_ART;
const NAV=[['general','General'],['pointers','Pointers'],['effects','Pointer defaults'],['drawing','Tools'],['controls','Shortcuts'],['presets','Presets & Backup'],['about','About']];
const CATALOG=parent.REVIEW_CATALOG.map(p=>({...p,enabled:true,available:true,custom:false}));
CATALOG.push({id:'mustard',name:'Mustard',art:'knit',enabled:true,available:true,custom:true});
const SOUND=['Thock','Click','Tock','Clack','Typewriter','Snap','Wood block','Pop','Boop','Blip','Coin','Pew','Squeak','Quack','Chirp'];
const INK=[['match','Match pointer','#9363cc'],['red','Red','#ec655e'],['orange','Orange','#ff8a00'],['yellow','Yellow','#edb623'],['green','Green','#519c77'],['blue','Blue','#4385c5'],['purple','Purple','#9363cc'],['white','White','#fff'],['black','Black','#292833']];
const TOOLS=['Pen','Rectangle','Arrow','Text','Number','Eraser','Highlighter'];
const COMMANDS={Pointer:['Pointer On/Off','Turn Pointer Off','Interact On/Off','Next Pointer','Previous Pointer','Tap Sound On/Off','Hold Gesture 1','Hold Gesture 2'],Drawing:['Clear Drawing','Undo Annotation','Redo Annotation','Match Ink to Pointer'],Presenting:['Take Screenshot','Capture Region…','Magnification On/Off','Toolbar Show/Hide','Open Settings']};
const S={page:'general',theme:'light',scenario:'ready',login:false,themePreference:'System',updates:true,autoUpdates:true,lastCheck:'Today at 9:41',accessibility:'Allowed',recordingPermission:'Allowed',
 capture:'Save and copy',folder:'Desktop',current:'lavender',pins:['lavender','glove','coral','plush','robot','laser'],quick:['glove','lavender','coral','plush','robot','laser'],query:'',filters:new Set(),filterOpen:false,
 defaults:{size:13,shadow:true,shadowStyle:'Original',soundEnabled:true,sound:'Wood block'},motion:{follow:'Responsive',swing:0,keepVisible:true},output:{muted:false,volume:70},magnifier:{zoom:2,diameter:240},
 overrides:{lavender:{size:16,sound:'Pop'}},gestureCustom:{},showToolbar:true,modifier:'Unassigned',keys:{},keyQuery:'',keyFilter:'All commands',keyError:{},recordingKey:null,conflictView:false,
 deckBusy:false,deckHost:true,deckMessage:'',practiceMode:'Draw',tool:'Pen',ink:'match',width:7,opacity:90,fade:'Fade',fadeDelay:6,smoothing:'Light',trailDelay:1,trailSpeed:200,practicePaths:[],practiceText:'Look here',
 selectedPreset:0,presets:[{name:'Workshop',pointer:'lavender',pins:6,off:2},{name:'Quiet demo',pointer:'glove',pins:4,off:0}],recovery:null,libraryRecovery:null,overrideRecovery:null,
 menu:null,chooser:null,modal:null,modalData:{},selectedPin:-1,open:{},importConflict:false,restoreError:false,customizing:null};
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const entry=id=>CATALOG.find(p=>p.id===id)||{id,name:id,available:false,enabled:false};
const effective=id=>({...S.defaults,...S.overrides[id]});
const customCount=id=>Object.keys(S.overrides[id]||{}).length;
const supportsShadow=id=>!['laser','spotlight'].includes(id);
const supportsStyle=id=>supportsShadow(id)&&id!=='presentation';
const isHand=id=>!['laser','spotlight','presentation'].includes(id);
const sizeLabel=id=>({laser:'Dot size',spotlight:'Aperture size',presentation:'Rod thickness'}[id]||'Hand size');
function art(id,full=false){const p=entry(id),key=p.art||id;if(ART[key])return `<img src="${full?(FULL_ART[key]||ART[key]):ART[key]}" alt="">`;return `<span class="native-art ${{presentation:'rod'}[id]||id}" aria-hidden="true"></span>`}
const button=(label,action,options='')=>`<button type="button" class="mbtn" data-action="${action}" ${options}>${label}</button>`;
const link=(label,action,options='')=>`<button type="button" class="textbtn" data-action="${action}" ${options}>${label}</button>`;
const row=(label,control,detail='',cls='')=>`<div class="row ${cls}"><div class="left"><span>${label}</span>${detail?`<span class="detail">${detail}</span>`:''}</div><div class="right">${control}</div></div>`;
const group=body=>`<div class="group">${body}</div>`;
const switcher=(label,key,value,extra='')=>`<label class="toggle"><input type="checkbox" aria-label="${esc(label)}" data-setting="${key}" ${value?'checked':''} ${extra}><span aria-hidden="true"></span></label>`;
const menu=(label,key,values,value,extra='')=>`<select aria-label="${esc(label)}" data-setting="${key}" ${extra}>${values.map(v=>`<option ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('')}</select>`;
const slider=(label,key,value,min,max,step,suffix,extra='')=>`<input type="range" aria-label="${esc(label)}" data-setting="${key}" min="${min}" max="${max}" step="${step}" value="${value}" data-suffix="${suffix}" ${extra}><output class="value">${value}${suffix}</output>`;
const radios=(label,key,values,value)=>`<div class="radio-options" role="group" aria-label="${label}">${values.map(v=>`<label><input type="radio" name="${key}" data-setting="${key}" value="${v}" ${v===value?'checked':''}>${v}</label>`).join('')}</div>`;
const section=(id,title,body,note='')=>`<section id="${id}"><h3>${title}</h3>${group(body)}${note?`<p class="subnote">${note}</p>`:''}</section>`;
const details=(id,title,value,body)=>`<details data-disclosure="${id}" ${S.open[id]?'open':''}><summary>${title}<span class="summary-value">${value}</span></summary>${body}</details>`;
const title=(name,subtitle)=>`<h2>${name}</h2><p class="subtitle">${subtitle}</p>`;
function pathGet(key){return key.split('.').reduce((o,k)=>o?.[k],S)}
function pathSet(key,value){const parts=key.split('.');let o=S;for(const p of parts.slice(0,-1)){if(!o[p])o[p]={};o=o[p]}o[parts.at(-1)]=value}
function changePage(page,focus){closeModal();S.page=page;S.menu=null;S.filterOpen=false;parent.postMessage({type:'page-request',page,control:focus},'*');render();if(focus)requestAnimationFrame(()=>focusSection(focus))}
function focusSection(name){const id={keyboard:'keyboard',quick:'quick-controls',toolbar:'toolbar',deck:'stream-deck'}[name]||name;const el=$(id);if(el){$('app-main').scrollTop=Math.max(0,el.offsetTop-$('app-main').offsetTop-8);el.classList.add('focused-section');setTimeout(()=>el.classList.remove('focused-section'),1200)}}
function permission(name,value,detail){const ok=value==='Allowed';return row(name,`<span class="status ${ok?'good':''}">${ok?'':'⚠ '}${value}</span>`+(!ok?button('Open System Settings…',name==='Accessibility'?'allow-drawing':'allow-recording'):''),detail)}
function general(){return title('General','Permissions, startup and app appearance.')+section('permissions','Permissions',permission('Accessibility',S.accessibility,'Drawing, tool keys and Quick controls.')+permission('Screen Recording',S.recordingPermission,'Screenshots and magnification.'))+section('startup','Startup and updates',row('Open at login',switcher('Open at login','login',S.login))+(S.updates?row('Check automatically',switcher('Check for updates automatically','autoUpdates',S.autoUpdates))+row('Last checked',button('Check Now','check-updates'),S.lastCheck):row('Updates','<span class="status">Unavailable</span>','Updates are not set up in this build.','disabled-row')))+section('appearance','App appearance',row('Theme',radios('App theme','themePreference',['System','Light','Dark'],S.themePreference)),'Applies to Settings, the toolbar and menus.')+`<p class="subnote">New to Look Here Please? ${link('Practice the Controls…','practice')}</p>`;}
function defaultPreview(){const count=customCount(S.current);return `<div class="defaults-preview"><div class="preview-controls"><strong>Default hand sample</strong>${menu('Sample background','previewBackground',['Light','Dark','Patterned'],S.previewBackground||'Light')}</div><div class="preview-sample" id="defaults-sample">${art('lavender',true)}<span class="hint">Shared values only</span></div><div class="preview-controls"><span>This sample uses the defaults below.</span><div class="actions">${button('Preview Tap','preview-tap')}${button('Preview Motion','preview-motion')}</div></div>${count?`<p class="subnote">${entry(S.current).name} has ${count} custom values. ${link('Review its settings…','customize-current')}</p>`:''}</div>`}
function defaults(){return title('Pointer defaults','Starting values for pointers, plus app-wide motion and sound.')+defaultPreview()+section('default-look','Look',row('Size',slider('Default size','defaults.size',S.defaults.size,4,20,1,'%'),'Relative to display height.')+row('Shadow',menu('Default shadow','defaultShadow',['Off','Original','Contact'],S.defaults.shadow?S.defaults.shadowStyle:'Off')),'Each pointer can override size, shadow and shadow style. Size also sets Spotlight aperture and rod thickness.')+section('default-sound','Tap sound',row('Tap sound',switcher('Default tap sound','defaults.soundEnabled',S.defaults.soundEnabled))+row('Sound',menu('Default tap sound choice','defaults.sound',SOUND,S.defaults.sound)+button('Preview','preview-sound',S.output.muted||S.output.volume===0?'disabled title="All app sounds are muted"':'')),'Each pointer can override these two values independently.')+section('app-output','App sound',row('Volume',button(S.output.muted?'Unmute':'Mute','toggle-mute',`aria-pressed="${S.output.muted}" aria-label="${S.output.muted?'Unmute all app sounds':'Mute all app sounds'}"`)+slider('App volume','output.volume',S.output.volume,0,100,1,'%')),S.output.muted?'All app sounds and sound previews are muted.':'Volume and mute apply to every pointer and sound preview.')+section('motion','Motion',row('Follow',radios('Follow behavior','motion.follow',['Original','Responsive'],S.motion.follow),S.motion.follow==='Original'?'Looser grip swing.':'Follows small movements closely and catches quick flicks.')+row('Tap swing',slider('Tap swing','motion.swing',S.motion.swing,0,2,.1,'×'))+row('Keep hand visible while interacting',switcher('Keep hand visible while interacting','motion.keepVisible',S.motion.keepVisible)),'Motion applies across the app. Reduce Motion turns tap swing off.');}
function toolbarFavorites(){return `<div class="group-label"><h3>Toolbar favorites</h3><span class="fine">${S.pins.length} of 8</span></div>${group(`<div class="slots toolbar-slots">${S.pins.map((id,i)=>`<button type="button" class="slot ${S.selectedPin===i?'selected':''}" draggable="true" data-pin-index="${i}" aria-label="Toolbar ${i+1}: ${esc(entry(id).name)}. ${entry(id).enabled?'Enabled':'Off'}. Open reorder actions.">${entry(id).available?art(id):'<span class="fine">⚠</span>'}<span class="slot-label">${i+1}</span></button>`).join('')}${S.pins.length<8?`<button class="slot" data-action="add-toolbar" aria-label="Add a toolbar favorite"><span style="font-size:22px">+</span><span class="slot-label">Add</span></button>`:''}</div>`)}<p class="subnote">Drag to reorder. Open a favorite for Move Left, Move Right or Unpin.</p>`}
function radialFavorites(){const pos=[['N',1,0],['NE',2,0],['E',2,1],['SE',2,2],['SW',0,2],['W',0,1]];return `<div class="quick-favorites"><div><h3>Quick controls favorites</h3><p class="fine">Six fixed directions.<br>Separate from the toolbar.</p>${link('Edit a slot…','edit-quick')}</div><div class="radial-favorites" aria-label="Quick controls pointer directions">${pos.map(([direction,x,y],i)=>`<button class="radial-slot" style="grid-column:${x+1};grid-row:${y+1}" data-quick-index="${i}" aria-label="${direction}: ${esc(entry(S.quick[i]).name)}. ${entry(S.quick[i]).enabled?'Enabled':'Off'}.">${entry(S.quick[i]).available?art(S.quick[i]):'<span class="fine">⚠</span>'}<span>${direction}</span></button>`).join('')}<span class="radial-center" style="grid-column:2;grid-row:2">Pointer</span><span class="radial-static" style="grid-column:1;grid-row:1">All</span><span class="radial-static" style="grid-column:2;grid-row:3">Back</span></div></div>`}
function pointerMenu(){if(!S.menu)return '';const p=entry(S.menu),pinned=S.pins.includes(p.id);return `<div class="pointer-actions" style="position:fixed;left:${S.menuX||170}px;top:${S.menuY||220}px" role="menu" aria-label="Actions for ${esc(p.name)}"><div class="fine">${esc(p.name)}</div><button role="menuitem" data-action="use-menu-pointer" ${!p.enabled||!p.available?'disabled':''}>Use This Pointer</button><button role="menuitemcheckbox" aria-checked="${p.enabled}" data-action="toggle-menu-enabled">${p.enabled?'✓ ':''}Enabled</button><button role="menuitem" data-action="toggle-menu-pin">${pinned?'Unpin from Toolbar':'Pin to Toolbar'}</button><button role="menuitem" data-action="assign-menu-quick">Add to Quick controls…</button><button role="menuitem" data-action="customize-menu">Customize…</button>${p.custom?'<button role="menuitem" data-action="remove-menu-hand" class="danger-link">Remove Hand…</button>':''}${!p.available?'<button role="menuitem" data-action="restore-artwork">Restore Artwork…</button>':''}</div>`}
function filteredCatalog(){return CATALOG.filter(p=>!p.removed&&p.name.toLowerCase().includes(S.query.toLowerCase())&&(!S.filters.has('Enabled')||p.enabled)&&(!S.filters.has('Pinned')||S.pins.includes(p.id))&&(!S.filters.has('Custom')||p.custom))}
function pointers(){const p=entry(S.current),items=filteredCatalog(),hidden=!items.some(e=>e.id===p.id);return title('Pointers','Choose a pointer and arrange your favorites.')+`<div class="current-strip">${art(S.current)}<div class="current-copy"><div class="fine">Current pointer</div><div class="current-name">${esc(p.name)}</div><span class="badge ${customCount(S.current)?'custom':''}">${customCount(S.current)?customCount(S.current)+' custom values':'Uses Pointer Defaults'}</span></div>${button('Customize…','customize-current')}</div>`+toolbarFavorites()+radialFavorites()+`<div class="library-tools sticky-library"><input type="search" id="pointer-search" placeholder="Search ${CATALOG.filter(e=>!e.removed).length} pointers" aria-label="Search all pointers" value="${esc(S.query)}">${button('Show'+(S.filters.size?' · '+S.filters.size:''),'show-filters',`aria-haspopup="menu" aria-expanded="${S.filterOpen}"`)}${button('New Hand…','new-hand')}</div>${S.filterOpen?`<div class="filter-menu" role="menu" aria-label="Filter pointers" style="position:fixed;left:${S.filterX||240}px;top:${S.filterY||440}px"><div class="fine">Combine filters</div>${['Enabled','Pinned','Custom'].map(f=>`<button role="menuitemcheckbox" aria-checked="${S.filters.has(f)}" data-filter-item="${f}">${S.filters.has(f)?'✓ ':''}${f}</button>`).join('')}${link('Show All','show-all')}</div>`:''}${S.filters.size||S.query?`<div class="filter-summary">${items.length} matches${S.filters.size?' · '+[...S.filters].join(' + '):''}${link('Show All','show-all')}</div>`:''}${hidden?`<div class="inline-message">${esc(p.name)} is hidden by filters. ${link('Show All','show-all')}</div>`:''}${S.libraryRecovery?`<div class="transaction">Removed ${esc(S.libraryRecovery.name)}.${button('Undo','undo-remove-hand')}</div>`:''}${pointerMenu()}<div class="gallery">${items.map(p=>`<div class="tile ${p.id===S.current?'selected':''} ${p.enabled?'':'disabled'}"><button class="select-pointer" data-pointer="${p.id}" ${!p.enabled||!p.available?'disabled':''} aria-pressed="${p.id===S.current}" aria-label="${esc(p.name)}, ${p.id===S.current?'selected, ':''}${p.enabled?'enabled':'off'}, ${S.pins.includes(p.id)?'pinned':'not pinned'}${p.custom?', custom':''}${p.available?'':', image unavailable'}">${p.available?art(p.id):'<span class="native-art unavailable">⚠</span>'}${esc(p.name)}<span class="tile-state">${p.id===S.current?'✓ ':''}${S.pins.includes(p.id)?'Pinned ':''}${!p.enabled?'Off ':''}${p.custom?'Custom ':''}${!p.available?'Image unavailable':''}</span></button><button class="more" data-menu="${p.id}" aria-label="Actions for ${esc(p.name)}" aria-haspopup="menu">···</button></div>`).join('')||`<div class="empty-state" style="grid-column:1/-1"><strong>No matching pointers</strong><p>Try a different name or show the full library.</p>${button('Show All','show-all')}</div>`}</div>`;}
function drawCaption(){if(S.fade==='Trail')return `The start of a pen line erases as you draw. Other marks fade after ${S.fadeDelay} seconds.`;return S.fade==='Keep'?'Marks stay until cleared.':`Whole marks fade after ${S.fadeDelay} seconds.`}
function practiceMarkup(){return `<div class="preview-controls"><strong>Practice drawing</strong><div class="actions">${button('Replay Sample','replay-sample')}${button('Undo','undo-practice',!S.practicePaths.length?'disabled':'')}${button('Clear','clear-practice',!S.practicePaths.length?'disabled':'')}</div></div><div class="preview-controls" style="margin-top:8px">${radios('Local practice mode','practiceMode',['Interact','Draw'],S.practiceMode)}<span class="fine">Only this canvas</span></div><div class="toolstrip" role="group" aria-label="Local practice tool">${TOOLS.map(t=>`<button data-tool="${t}" class="${S.tool===t?'active':''}" aria-pressed="${S.tool===t}">${t}</button>`).join('')}</div>${S.tool==='Text'?`<input type="text" data-setting="practiceText" aria-label="Practice text" value="${esc(S.practiceText)}" style="width:100%;margin-bottom:7px">`:''}<div class="canvas" id="practice-canvas" role="img" aria-label="Local ${S.tool} practice. Replay Sample demonstrates the current settings."><svg id="practice-svg" viewBox="0 0 400 112" preserveAspectRatio="none">${S.practicePaths.join('')}</svg></div><p class="subnote">${drawCaption()} ${S.practiceMode==='Draw'?'Draw here to try the current tool.':'Interact passes over the canvas without drawing.'}</p>`}
function tools(){return title('Tools','Drawing, magnification and screenshots.')+`<div class="section-jump" aria-label="Jump to tool settings"><a href="#drawing-ink">Drawing</a><a href="#magnification">Magnification</a><a href="#screenshots">Screenshots</a></div>`+practiceMarkup()+section('drawing-ink','Ink',row('Color',`<div class="swatches refined-swatches">${INK.map(([id,name,color])=>`<button class="ink-hit ${S.ink===id?'active':''}" data-ink="${id}" aria-label="${name}" aria-pressed="${S.ink===id}" style="--swatch:${color}"><span class="ink-dot ${id==='match'?'match':''}"></span></button>`).join('')}</div>`)+row('Line width',slider('Line width','width',S.width,2,20,1,' pt'))+row('Opacity',slider('Ink opacity','opacity',S.opacity,10,100,5,'%')))+section('fading','Fading',row('Behavior',radios('Fading behavior','fade',['Keep','Fade','Trail'],S.fade))+(S.fade==='Keep'?'':row(S.fade==='Trail'?'Other marks fade after':'Fade after',menu('Fade delay','fadeDelay',[3,6,10],S.fadeDelay))))+group(details('timing','Smoothing and trail timing',S.smoothing+(S.fade==='Trail'?` · ${S.trailDelay}s · ${S.trailSpeed}pt/s`:''),row('Smoothing',menu('Smoothing','smoothing',['Off','Very light','Light','Medium'],S.smoothing))+(S.fade==='Trail'?row('Trail delay',slider('Trail delay','trailDelay',S.trailDelay,.2,3,.2,' s'))+row('Trail speed',slider('Trail speed','trailSpeed',S.trailSpeed,40,600,20,' pt/s')):'')))+section('magnification','Magnification',row('Zoom',slider('Magnification zoom','magnifier.zoom',S.magnifier.zoom,1.5,6,.5,'×'))+row('Lens size',slider('Lens size','magnifier.diameter',S.magnifier.diameter,160,480,16,' pt')),'Toggle from the toolbar, menu or a shortcut. The lens stays on the current display and marks the click location.')+(S.recordingPermission==='Allowed'?'':`<div class="inline-message error-message">Screen Recording is ${S.recordingPermission.toLowerCase()}. ${link('Review Access…','go-permissions')}</div>`)+section('screenshots','Screenshots',row('After capturing',menu('Screenshot destination','capture',['Save and copy','Save to folder','Copy to clipboard'],S.capture))+(S.capture==='Copy to clipboard'?'':row('Save folder',button('Choose…','choose-folder'),esc(S.folder))),'Captures include the current display, pointer and annotations.');}
const keyScope=c=>['Pointer On/Off','Clear Drawing'].includes(c)?'Global · Works with the pointer off':['Undo Annotation','Redo Annotation'].includes(c)?'While drawing · Interact off':TOOLS.includes(c)?'While drawing · Single keys allowed':c.includes('Gesture')?(isHand(S.current)&&entry(S.current).available?'Hold while a hand is on':'Choose a hand with gesture artwork'):(c==='Tap Sound On/Off'?'Current pointer only · App mute still applies':'While the pointer is on');
function conflictKeys(){const counts={};for(const v of Object.values(S.keys))if(v)counts[v]=(counts[v]||0)+1;return Object.keys(S.keys).filter(c=>counts[S.keys[c]]>1)}
function keyRows(commands){const conflicts=conflictKeys();return commands.filter(c=>c.toLowerCase().includes(S.keyQuery.toLowerCase())&&(S.keyFilter!=='Assigned'||S.keys[c])&&(!S.conflictView||conflicts.includes(c))).map(c=>row(`${esc(c)}<span class="scope-label">${esc(keyScope(c))}</span>`,`<button class="mbtn keyfield ${S.keys[c]?'assigned':''}" data-key="${esc(c)}" aria-label="Record ${esc(c)} shortcut">${S.recordingKey===c?'Press keys…':esc(S.keys[c]||'Record shortcut')}</button>`+(S.keys[c]?link('Clear','clear-key',`data-command="${esc(c)}" aria-label="Clear ${esc(c)} shortcut"`):''),'','key-row')+(conflicts.includes(c)?`<div class="row-error">⚠ Also assigned to ${esc(conflicts.find(k=>k!==c&&S.keys[k]===S.keys[c])||'another command')}. Record another key or Clear.</div>`:'')+(S.keyError[c]?`<div class="row-error">${esc(S.keyError[c])}</div>`:'')).join('')}
function commandGroup(name,commands,open=true){const visible=commands.filter(c=>c.toLowerCase().includes(S.keyQuery.toLowerCase())&&(S.keyFilter!=='Assigned'||S.keys[c])&&(!S.conflictView||conflictKeys().includes(c)));if(!visible.length)return '';const assigned=commands.filter(c=>S.keys[c]).length,conflicts=commands.filter(c=>conflictKeys().includes(c)).length;return `<div class="key-group"><div class="group-label"><h3>${name}</h3><span class="fine">${conflicts?'⚠ '+conflicts+' conflict'+(conflicts>1?'s':''):assigned+' of '+commands.length+' set'}</span></div>${open?group(keyRows(commands)):group(`<details data-disclosure="keys-${name}" ${S.open['keys-'+name]||assigned||conflicts||S.keyQuery?'open':''}><summary>${name} shortcuts</summary>${keyRows(commands)}</details>`)}</div>`}
function shortcuts(){const conflicts=conflictKeys();return title('Shortcuts & controls','Toolbar, Quick controls, keyboard shortcuts and Stream Deck.')+(conflicts.length?`<div class="inline-message error-message"><span>⚠ ${conflicts.length} commands use the same shortcut.</span>${button(S.conflictView?'Show All':'Show Conflicts','show-conflicts')}</div>`:'')+`<div class="section-jump"><a href="#toolbar">Toolbar</a><a href="#quick-controls">Quick controls</a><a href="#keyboard">Keyboard</a><a href="#stream-deck">Stream Deck</a></div>`+section('toolbar','Toolbar',row('Show toolbar',switcher('Show toolbar','showToolbar',S.showToolbar),'Appears at pointer startup and while the cursor is nearby.')+row('Position',button('Reset Position','reset-position')),'Favorites are arranged in Pointers.')+section('quick-controls','Quick controls',row('Hold to open',menu('Hold-to-open modifier','modifier',['Unassigned','Option','Control','Shift','Command'],S.modifier)+(S.modifier!=='Unassigned'?link('Clear','clear-modifier') :''))+row('Open Quick controls',`<button class="mbtn keyfield" data-key="Open Quick controls">${S.recordingKey==='Open Quick controls'?'Press keys…':esc(S.keys['Open Quick controls']||'Record shortcut')}</button>`+(S.keys['Open Quick controls']?link('Clear','clear-key','data-command="Open Quick controls"'):'')),'Hold, move to a choice, release. Desktop use needs Accessibility and Pointer On.')+`<div class="preview-controls">${link('Practice Quick controls…','practice-quick')}${link('Edit favorites in Pointers…','go-favorites')}</div><section id="keyboard"><h3>Keyboard shortcuts</h3><div class="command-filter"><input type="search" id="key-search" placeholder="Find a command" aria-label="Find a command" value="${esc(S.keyQuery)}">${menu('Command filter','keyFilter',['All commands','Assigned'],S.keyFilter)}</div><p class="subnote">Click a field and press keys. Escape cancels. Clear removes an assignment.</p>${commandGroup('Pointer',COMMANDS.Pointer)}${commandGroup('Presenting',COMMANDS.Presenting)}${commandGroup('Drawing',COMMANDS.Drawing,false)}${group(details('tool-keys','Tool keys · Interact off',TOOLS.filter(c=>S.keys[c]).length+' of 7 set',`<p class="subnote" style="padding:0 12px 8px">Single keys work here. They pause while you type.</p>${keyRows(TOOLS)}`))}<p class="subnote">Standard editing keys keep working in text fields. ⌘, opens Settings.</p></section>`+section('stream-deck','Stream Deck',row('Bundled plugin 1.1.0.0',button(S.deckBusy?'Opening…':'Install Plugin…','install-deck',S.deckBusy?'disabled':''),'Requires Stream Deck 6.5 or later.')+(!S.deckHost?row('Stream Deck app',link('Download Stream Deck…','download-deck'),'Install the app before adding the plugin.'):'')+(S.deckMessage?row('Status','<span class="fine">'+esc(S.deckMessage)+'</span>'):''),'Finish installation in Stream Deck, then add actions to your keys.');}
function recoveryBanner(){return S.recovery?`<div class="transaction"><span>${esc(S.recovery.title)}</span><div class="right">${button('Undo','undo-transaction')}${link('Dismiss','dismiss-recovery')}</div></div>`:''}
function presets(){const p=S.presets[S.selectedPreset];return title('Presets & Backup','Save pointer, ink and sound setups.')+recoveryBanner()+section('saved-presets','Saved presets',S.presets.length?S.presets.map((p,i)=>`<div class="preset-row ${i===S.selectedPreset?'selected':''}"><button class="preset-choice" data-preset="${i}" aria-pressed="${i===S.selectedPreset}">${art(p.pointer)}<span><strong>${esc(p.name)}</strong><span class="detail">${esc(entry(p.pointer).name)} · ${p.pins} toolbar favorites · ${p.off} pointers off</span></span></button></div>`).join(''):`<div class="empty-state"><strong>No saved presets</strong><p>Save the current setup to use it again.</p></div>`)+`<div class="preset-actions">${button('Save Current Setup…','save-preset')}${p?button('Apply','apply-preset')+link('Update from Current Setup','update-preset')+link('Remove…','remove-preset','class="danger-link"'):''}</div><p class="subnote">Applying keeps Pointer On/Off, Interact, shortcuts and startup unchanged. Unavailable pointers keep their saved settings while an available pointer is used.</p>`+section('backup','Backup',row('Settings and artwork',button('Export…','export-backup')+button('Import…','import-backup')),'Shortcuts, startup, screenshot folders and display positions stay on this Mac.')+group(details('backup-included','What is included','',`<div class="row"><div class="left">Supported settings, pointer defaults, per-pointer overrides, presets, custom hands and gesture artwork. Existing files are kept; conflicting imports stop before changes.</div></div>`)+details('recovery-folder','Recovery copies','',row('Local recovery folder',button('Show in Finder','show-recovery'))))+`<div class="recovery-row">${button('Reset All Settings…','reset-all','style="color:#b54f4a"')}</div>`;}
