function render(preserveScroll=false){const top=$('app-main').scrollTop;$('app').classList.toggle('dark',S.theme==='dark');$('app-nav').innerHTML=NAV.map(([id,label])=>`<button data-page="${id}" class="${S.page===id?'active':''}" aria-current="${S.page===id?'page':'false'}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[id]}"></path></svg>${label}</button>`).join('')+`<div class="app-footer"><img src="${parent.REVIEW_ICON}" alt="">Look Here Please</div>`;$('app-main').innerHTML=({general,pointers,effects:defaults,drawing:tools,controls:shortcuts,presets,about}[S.page])();$('app-main').scrollTop=preserveScroll?top:0;syncVisuals();if(S.modal)renderModal();requestAnimationFrame(reportSize)}
function syncVisuals(){const img=$('defaults-sample')?.querySelector('img');if(img)img.style.transform=`scale(${S.defaults.size/13})`;const well=$('defaults-sample');if(well)well.style.background=S.previewBackground==='Dark'?'#302b36':S.previewBackground==='Patterned'?'repeating-conic-gradient(#d9d0e3 0% 25%,#f1eaf6 0% 50%) 0 0 / 24px 24px':'#f0edf6';}
let toastTimeout,returnFocus=null;
