function fieldReset(id,field){return S.overrides[id]?.[field]!==undefined?`<span class="badge custom">Custom</span><button class="reset-value" data-reset-field="${field}" aria-label="Use default ${field} for ${esc(entry(id).name)}" title="Use this field's shared default">↶</button>`:''}
