function openPinMenu(b){const index=S.selectedPin;S.menu=null;const host=document.createElement('div');host.className='pin-menu pointer-actions';host.setAttribute('role','menu');host.innerHTML=`<div class="fine">${esc(entry(S.pins[index]).name)}</div>${button('Move Left','move-pin-left',index===0?'disabled':'')}${button('Move Right','move-pin-right',index===S.pins.length-1?'disabled':'')}${button('Unpin from Toolbar','unpin-selected',S.pins.length===1?'disabled':'')}`;document.querySelector('.pin-menu')?.remove();b.closest('.group').append(host);host.querySelector('button:not(:disabled)').focus();}
