document.addEventListener('input',e=>{const el=e.target;if(el.id==='pointer-search'||el.id==='key-search'||el.id==='chooser-search'){const pos=el.selectionStart,id=el.id;if(id==='pointer-search')S.query=el.value;if(id==='key-search')S.keyQuery=el.value;if(id==='chooser-search')S.modalData.query=el.value;id==='chooser-search'?renderModal():render(true);const next=$(id);next?.focus();try{next?.setSelectionRange(pos,pos)}catch{}return}if(el.id==='hand-name'||el.id==='hand-description'||el.id==='preset-name'){const id=el.id,val=el.value,pos=el.selectionStart;S.modalData[id==='hand-name'?'name':id==='hand-description'?'description':'name']=val;const action=id==='preset-name'?'confirm-save-preset':'add-hand';const button=$('modal-layer').querySelector('[data-action="'+action+'"]');if(button)button.disabled=id==='preset-name'?!val.trim():!S.modalData.name?.trim()||!S.modalData.url;return}if(el.type==='range'){if(S.restoreError&&el.dataset.setting.startsWith('overrides.')){toast('Unable to save pointer settings. Restore a valid backup, then try again.');render(true);return}const value=Number(el.value);pathSet(el.dataset.setting,value);el.nextElementSibling.textContent=value+el.dataset.suffix;syncVisuals();if(S.modal==='customize'){const id=S.modalData.id;const row=el.closest('.row');if(!row.querySelector('.reset-value'))row.querySelector('.right').insertAdjacentHTML('beforeend',fieldReset(id,el.dataset.setting.split('.').at(-1)));}return}});
