function readHandFile(file){if(!file)return;if(file.type!=='image/png'){S.modalData.error='Choose a PNG with a transparent background.';renderModal();return}const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const c=document.createElement('canvas');c.width=64;c.height=64;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,64,64);const pixels=ctx.getImageData(0,0,64,64).data;let transparent=false;for(let i=3;i<pixels.length;i+=4)if(pixels[i]<20){transparent=true;break}if(!transparent){S.modalData.error='This image has an opaque background. Choose a transparent PNG.';S.modalData.url=null}else{S.modalData.url=reader.result;S.modalData.error='';if(!S.modalData.name)S.modalData.name=file.name.replace(/\.png$/i,'').slice(0,16)}renderModal()};image.onerror=()=>{S.modalData.error='Unable to read this PNG. Choose another image.';renderModal()};image.src=reader.result};reader.readAsDataURL(file)}
