document.addEventListener('keydown',e=>{const activeMenu=document.querySelector('[role=menu]');if(activeMenu&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=[...activeMenu.querySelectorAll('button:not(:disabled)')],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();return}if(e.key==='Enter'&&S.modal&&!e.target.closest('button,select,summary')){const action=S.modal==='new-hand'?'add-hand':S.modal==='save-preset'?'confirm-save-preset':null;const commit=action&&document.querySelector('[data-action="'+action+'"]');if(commit&&!commit.disabled){e.preventDefault();commit.click();return}}if(S.recordingKey){e.preventDefault();const c=S.recordingKey;if(e.key==='Escape'){S.recordingKey=null;render(true);return}if(['Shift','Alt','Control','Meta'].includes(e.key))return;if(e.key==='Backspace'||e.key==='Delete'){delete S.keys[c];S.recordingKey=null;render(true);return}const modifiers=(e.ctrlKey?'⌃':'')+(e.altKey?'⌥':'')+(e.shiftKey?'⇧':'')+(e.metaKey?'⌘':'');const globalModifier=e.ctrlKey||e.altKey||e.metaKey;if(!globalModifier&&!(TOOLS.includes(c)&&/^[a-z]$/i.test(e.key))){S.keyError[c]='Add Control, Option or Command for a global command.';S.recordingKey=null;render(true);return}if(e.metaKey&&!e.altKey&&!e.ctrlKey&&((e.shiftKey&&e.key.toLowerCase()==='z')||(!e.shiftKey&&['c','v','x','a','z','w','q','n','o','s','f','p',','].includes(e.key.toLowerCase())))){S.keyError[c]='That shortcut is reserved for standard Mac editing or app commands.';S.recordingKey=null;render(true);return}S.keys[c]=modifiers+e.key.toUpperCase();delete S.keyError[c];S.recordingKey=null;render(true);return}if(e.key==='Escape'){if(S.filterOpen){S.filterOpen=false;render(true);return}if(S.modal){closeModal();return}if(S.menu){S.menu=null;render(true);return}document.querySelector('.pin-menu')?.remove()}if(e.key==='Tab'&&S.modal){const nodes=[...$('modal-layer').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary,a[href]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('sheet'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function inkColor(){return INK.find(([id])=>id===S.ink)?.[2]||'#9363cc'}
function samplePath(){const color=inkColor(),opacity=S.opacity/100;const attrs=`stroke="${color}" stroke-width="${S.width}" opacity="${opacity}" fill="none"`;if(S.tool==='Rectangle')return `<rect x="95" y="23" width="180" height="65" rx="4" ${attrs}/>`;if(S.tool==='Arrow')return `<path d="M90 80L290 30M270 25L290 30L282 50" ${attrs}/>`;if(S.tool==='Text')return `<text x="75" y="65" font-size="26" fill="${color}">${esc(S.practiceText)}</text>`;if(S.tool==='Number')return `<circle cx="200" cy="56" r="23" fill="${color}"/><text x="200" y="64" text-anchor="middle" fill="white" font-size="23">1</text>`;return `<path d="M45 74Q105 16 155 65T315 54" ${attrs} stroke-linecap="round"/>`}
function replaySample(){S.practicePaths=[samplePath()]}
function animatePractice(){const svg=$('practice-svg');if(!svg||S.fade==='Keep'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;svg.animate([{opacity:1},{opacity:1},{opacity:0}],{duration:S.fade==='Trail'?1800:Math.min(10000,S.fadeDelay*1000),fill:'none'});}
let stroke=null;document.addEventListener('pointerdown',e=>{const canvas=e.target.closest('#practice-canvas');if(!canvas||S.practiceMode!=='Draw')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();stroke={points:[[400*(e.clientX-r.left)/r.width,112*(e.clientY-r.top)/r.height]],before:[...S.practicePaths]};if(S.tool==='Eraser'){S.practicePaths.pop();render(true);stroke=null}});document.addEventListener('pointermove',e=>{if(!stroke)return;const canvas=$('practice-canvas');if(!canvas)return;const r=canvas.getBoundingClientRect();stroke.points.push([400*(e.clientX-r.left)/r.width,112*(e.clientY-r.top)/r.height]);let d=stroke.points.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join('');$('practice-svg').innerHTML=stroke.before.join('')+`<path d="${d}" fill="none" stroke="${inkColor()}" stroke-width="${S.tool==='Highlighter'?S.width*2:S.width}" opacity="${S.tool==='Highlighter'?0.35:S.opacity/100}" stroke-linecap="round"/>`});document.addEventListener('pointerup',()=>{if(!stroke)return;S.practicePaths=[$('practice-svg').innerHTML];stroke=null;render(true);animatePractice()});


